  margin-bottom: 16px;
  padding: 16px;
  background: #1a2230;
  border: 1px solid #2a3550;
  border-radius: 12px;
}
.panel h2 { margin: 0 0 4px; font-size: 16px; color: #f27d26; }
.panel p { margin: 0 0 10px; color: #8b98ab; }
.panel code {
  padding: 2px 6px;
  background: #0b0f14;
  border-radius: 4px;
  color: #f2c14e;
  font-size: 13px;
