  display: inline-block;
  width: 14px;
  height: 14px;
  margin-right: 8px;
  border-radius: 3px;
  vertical-align: -2px;
}
.swatch-a { background: #4fa3e3; }
.swatch-b { background: #b07cff; }
.swatch-c { background: #f2c14e; }

/* 下面三条规则同时选中了 #champion。每条右边是它的优先级：(id 个数，class 个数，标签个数) */
#champion { background: #4fa3e3; }     /* (1,0,0) 蓝色 */
.panel .box { background: #b07cff; }   /* (0,2,0) 紫色 */
.box { background: #f2c14e; }          /* (0,1,0) 黄色 */

/* 方块的外观，和胜负无关 */
.box {
  padding: 20px;
  border-radius: 10px;
  color: #12181f;
  font-weight: 700;
}

/* 第 1 步：优先级和第一条 #champion 打平 (1,0,0)，但写在后面，所以它赢
   （写成 #champion.box 是 (1,1,0)，优先级更高，放在哪都赢；写成 .box 则 (0,1,0) 会输） */
#champion { background: #3ecf8e; }


/* ═══════════ 第 2 关：类与伪类 ═══════════ */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 12px;
}
.card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px;
  background: #0b0f14;
