/* a. 后代选择器：空格表示「里面的」——卡片里面的 <strong> */
.card strong { color: #ffffff; }

/* b. 两个 class 连着写：必须同时具有 card 和 featured */
.card.featured { border-color: #f27d26; }

/* c. 伪类 :hover：鼠标悬停在这个元素上时 */
.card:hover {
  border-color: #3ecf8e;
  transform: translateY(-2px);
}

/* d. 结构伪类：:first-child / :last-child 表示「作为父元素的第一个 / 最后一个孩子」
   它们的优先级 (0,2,1) 高于上面 a 的 (0,1,1)，所以能盖过白色 */
.cards .card:first-child strong { color: #3ecf8e; }
.cards .card:last-child strong { color: #f2c14e; }


/* ═══════════ 第 3 关：继承与盒模型 ═══════════ */
/* 刻度条：宽度固定 240px，用来对比内层盒子的实际宽度（不要改） */
.ruler {
  width: 240px;
  height: 8px;
  margin-bottom: 8px;
  border-radius: 4px;
  background: repeating-linear-gradient(90deg, #8b98ab 0 12px, #12181f 12px 24px);
}

/* 外层盒子：紫色实线是 border，线内的空白是 padding，盒子上下的透明留白是 margin */
.outer {
  margin: 24px 0;
  padding: 16px;
  border: 6px solid #b07cff;
  background: #3d2f4f;
  border-radius: 8px;
  color: #f2c14e;      /* a. 内层盒子没有自己的 color 时，会继承这个颜色 */
}

.inner {
  width: 240px;
  padding: 16px;
  border: 4px solid #f27d26;
  background: #24404f;
  color: #3ecf8e;          /* b. 自己写了 color，就不再继承外层的 */
  box-sizing: border-box;  /* c. width 把 padding 和 border 也算进去：实际宽度正好 240px */
}

