  font-family: system-ui, "Microsoft YaHei", sans-serif;
}
.page-head { max-width: 680px; margin: 0 auto 16px; }
.page-head h1 { margin: 0 0 4px; font-size: 22px; }
.page-head p { margin: 0; color: #8b98ab; font-size: 13px; }

/* ═══════ 网格容器 ═══════ */
.gallery {
  max-width: 680px;   /* 最宽 680px，居中 */
  margin: 0 auto;
  /* TODO（第 1 步）：把这个容器变成网格，补上四行：
         display: grid;
         grid-template-columns: repeat(3, 1fr);   3 列，每列等宽
         grid-auto-rows: 150px;                   每一行 150px 高
         gap: 12px;                               格子之间的缝 */
  /* TODO（第 3 步）：把 grid-template-columns 的值换成 repeat(auto-fit, minmax(130px, 1fr)) */
}

/* ═══════ 跨行跨列（第 2 步）═══════ */
/* TODO：.featured 横跨 2 列、纵跨 2 行：grid-column: span 2; grid-row: span 2; */
/* TODO：.tall 只纵跨 2 行：grid-row: span 2; */
/* TODO：.wide 只横跨 2 列：grid-column: span 2; */


/* ═══════ 卡片外观（不用改）═══════ */
.card {
  position: relative;
  display: flex;
  align-items: flex-end;
  box-sizing: border-box;   /* 让下面的 150px 把内边距也算进去，卡片正好填满一个 150px 高的格子 */
  min-height: 150px;
  margin: 0;
  padding: 14px;
  border-radius: 12px;
  color: #ffffff;
