  transition: transform 0.15s;
}
/* 卡片底部压一层由透明到半透明的黑色，保证浅色渐变上的白字也看得清 */
.card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(rgba(0, 0, 0, 0) 40%, rgba(0, 0, 0, 0.5));
}
