.c-sunrise { background: linear-gradient(135deg, #f27d26, #8f2d00); }
.c-mist { background: linear-gradient(160deg, #7f9bc0, #33415c); }
.c-dusk { background: linear-gradient(180deg, #b07cff, #3d2f4f); }
.c-sea { background: linear-gradient(135deg, #4fa3e3, #16425b); }
