  const item = document.createElement('li');
  item.className = 'item';

  // 2. 创建勾选框
  const box = document.createElement('input');
  box.type = 'checkbox';

  // 3. 创建文字：textContent 会把内容当作纯文本写进去
  const label = document.createElement('span');
  label.textContent = text;

  // 4. 创建删除按钮
  const del = document.createElement('button');
  del.type = 'button';
  del.className = 'del';
  del.textContent = '×';

  // 5. 先把孩子挂到 <li> 上，再把 <li> 挂到列表上
  item.append(box, label, del);
  list.append(item);

  // 6. 新增了一条：底部的数量和「还没有待办」的提示要跟着更新（updateCount 在第 2 步补全）
  updateCount();
}

// 放在 addItem 里（三个元素都创建完之后）
box.addEventListener('change', () => {
  // 第二个参数为 true 就加上 done，为 false 就去掉
  item.classList.toggle('done', box.checked);
  updateCount();
});

// 剩余数量统一在这里算：添加、勾选、删除之后只要调用它，数字就一定是对的
function updateCount() {
  // 还没完成的条数：选出不带 done 的条目
  const left = list.querySelectorAll('.item:not(.done)').length;
