const lines = orders.map((o) => `${o.id} ${o.product} ×${o.qty} = ${amountOf(o)}`);
lines.forEach((line) => console.log(line));

// 等价的 for 循环写法——对比一下哪个更能看出「意图」
const lines2 = [];
for (const o of orders) {
  lines2.push(`${o.id} ${o.product} ×${o.qty} = ${amountOf(o)}`);
}

// filter：回调返回 true 的留下，返回 false 的丢掉，结果是一个新数组
const paidOrders = orders.filter((o) => o.paid);
console.log(paidOrders.map((o) => o.id).join(', '));   // A101, A103, A104, A106

// 回调里不用写 if...else，直接写一个判断表达式
const bigOrders = orders.filter((o) => amountOf(o) > 300);
console.log(bigOrders.map((o) => o.id).join(', '));    // A103, A106

// 两个条件可以拼在一起：已付款、并且金额超过 300
const paidBig = orders.filter((o) => o.paid && amountOf(o) > 300);

// 求和：sum 是上一次累计的结果，第二个参数 0 是 sum 的初始值（千万别漏）
const total = paidOrders.reduce((sum, o) => sum + amountOf(o), 0);
console.log(total);   // 1332

// 分组统计：让累计值 acc 是一个对象
const byCategory = orders.reduce((acc, o) => {
  acc[o.category] = (acc[o.category] || 0) + o.qty;   // 这个品类第一次出现时还不存在，用 || 0 兜底
  return acc;                                         // 必须返回 acc，它会被带到下一轮
}, {});
console.log(byCategory);   // { 红酒: 9, 白酒: 2, 起泡酒: 2 }

// 三个方法串成一条链
const chained = orders.filter((o) => o.paid).map(amountOf).reduce((sum, n) => sum + n, 0);
console.log(chained);     // 1332

