  { gap: 20, text: 'aaa' },
  { gap: 20, text: 'aaaa' },
  { gap: 20, text: 'aaaaa' },
]);

console.log('\n脚本结束。记法：防抖等用户「停下来」才执行，节流控制「多久最多执行一次」。');

