-- 选出两列，并用 AS 给它们起中文别名
SELECT id AS 编号, budget AS 预算 FROM departments;

-- AS 的左边也可以是一个算式
SELECT name, budget * 2 AS 明年预算 FROM departments;

-- 不去重：每个部门一行，「北京」会出现 3 次
SELECT location FROM departments;

-- 加上 DISTINCT：完全相同的行只留一行
SELECT DISTINCT location FROM departments;

-- 先按入职日期从早到晚排序，再取前 3 行：最早入职的 3 个人
SELECT name, hire_date FROM employees ORDER BY hire_date LIMIT 3;

-- LIMIT n OFFSET m：跳过前 m 行，再取 n 行
SELECT name, hire_date FROM employees ORDER BY hire_date LIMIT 3 OFFSET 3;

-- 比较运算符：=、>、>=、<、<=、<>（不等于）
SELECT name, salary FROM employees WHERE salary < 12000;

-- 多个条件用 AND / OR 连接，NOT 表示取反
SELECT name, dept_id, salary FROM employees WHERE dept_id = 5 AND salary >= 14000;

-- BETWEEN：闭区间，包含两端
SELECT name, salary FROM employees WHERE salary BETWEEN 10000 AND 13000;

-- IN：等于其中任意一个就保留
SELECT name, location FROM departments WHERE id IN (1, 3, 5);

-- LIKE：% 匹配任意多个字符，以「总监」结尾的职位都算
SELECT name, title FROM employees WHERE title LIKE '%总监';

-- ORDER BY 多列：先按第 1 个键排，相同的再按第 2 个键排。DESC 是降序，ASC（可省略）是升序
SELECT name, dept_id, salary FROM employees WHERE dept_id = 5 ORDER BY salary DESC;

-- 聚合函数把一列的许多值算成一个数
SELECT MAX(salary) AS 最高月薪, MIN(salary) AS 最低月薪, SUM(salary) AS 月薪总额 FROM employees;

-- 结果带很长的小数时，用 ROUND(x, 2) 保留两位
SELECT ROUND(AVG(salary), 2) AS 平均月薪 FROM employees;

