# 站点配置文件：/etc/nginx/sites-available/default
# 一个 server 块就是一台「虚拟主机」：谁监听、文件从哪找、请求怎么处理，都写在这里

server {
    # Step 1：监听 8080；default_server 表示这个端口上没有匹配到其它 server 时由它兜底
    listen 8080 default_server;

    # Step 1：静态文件的根目录——URL 里的路径会拼在它后面去找文件
    root /var/www/lab/dist;

    # 访问 / 时默认返回的文件
    index index.html;

    # Step 1 + 2：处理所有请求。try_files 从左到右依次尝试：
    #   $uri          按请求路径找文件（/style.css → /var/www/lab/dist/style.css）
    #   $uri/         再当目录找（找它下面的 index.html）
    #   /index.html   都没有就在服务器内部跳转去取首页（状态码 200，路由交给前端处理）
    location / {
        try_files $uri $uri/ /index.html;
    }

    # Step 3：以 /api/ 开头的请求转发给后端（它的前缀更长，优先于 location / 匹配）
    location /api/ {
        proxy_pass http://127.0.0.1:3000;
        # 后端收到的连接来自 nginx，这里把客户端的原始信息补进请求头
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}

